list_aliases.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.aliases().listAliases(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("aliases")) {
    Map<?, ?> alias = (Map<?, ?>) row;
    System.out.println(alias.get("id") + " " + alias.get("alias"));
}
Map<?, ?> pagination = (Map<?, ?>) body.get("pagination");
System.out.println(pagination.get("total") + " " + pagination.get("has_next"));

