import com.webcommander.sdk.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.aliases().createAlias(Map.of("alias", "shop.example.com"));
Map<?, ?> alias = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("alias");
System.out.println(alias.get("id") + " " + alias.get("alias") + " " + alias.get("created_at"));
